export const uid=()=>crypto.randomUUID();
export const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
export const monthOf=d=>d.slice(0,7);
export const rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
export const categories=[{id:'food',name:'Makan & minum',type:'expense',icon:'☕',color:'#e2a463'},{id:'shopping',name:'Belanja',type:'expense',icon:'▧',color:'#a69bd5'},{id:'transport',name:'Transportasi',type:'expense',icon:'↗',color:'#80accc'},{id:'bills',name:'Tagihan',type:'expense',icon:'▤',color:'#e28684'},{id:'fun',name:'Hiburan',type:'expense',icon:'♫',color:'#83b4a3'},{id:'health',name:'Kesehatan',type:'expense',icon:'♡',color:'#bc9ac2'},{id:'education',name:'Pendidikan',type:'expense',icon:'▣',color:'#bdaf70'},{id:'other',name:'Lainnya',type:'expense',icon:'⋯',color:'#a3aea6'},{id:'salary',name:'Gaji',type:'income',icon:'↓',color:'#5f8b70'},{id:'freelance',name:'Freelance',type:'income',icon:'◇',color:'#89b392'},{id:'gift',name:'Pemasukan lain',type:'income',icon:'✧',color:'#a5bf8a'}];
export function empty(){return{version:1,accounts:[{id:'cash',name:'Tunai',kind:'cash',opening:0,color:'#b7ce9b'}],categories:structuredClone(categories),transactions:[],budgets:[],goals:[],bills:[],name:'Teman'}}
export function balance(s,id){return s.accounts.find(a=>a.id===id).opening+s.transactions.reduce((n,t)=>n+(t.account===id?(t.type==='income'?t.amount:-t.amount):0)+(t.type==='transfer'&&t.to===id?t.amount:0),0)}
export function monthly(s,m){const ts=s.transactions.filter(t=>monthOf(t.date)===m),income=ts.filter(t=>t.type==='income').reduce((n,t)=>n+t.amount,0),expense=ts.filter(t=>t.type==='expense').reduce((n,t)=>n+t.amount,0);return{ts,income,expense,net:income-expense}}
export function spent(s,m,c){return monthly(s,m).ts.filter(t=>t.type==='expense'&&t.category===c).reduce((n,t)=>n+t.amount,0)}
export function isDate(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===v}
export function amount(v,zero=false){return Number.isSafeInteger(v)&&v>=(zero?0:1)&&v<=1e12}
export function validate(s){const fail=()=>{throw Error('Format backup tidak valid. Gunakan file JSON backup RuangUang.')};if(!s||s.version!==1||typeof s.name!=='string'||s.name.length>60)fail();for(const k of ['accounts','categories','transactions','budgets','goals','bills']){if(!Array.isArray(s[k])||s[k].length>50000)fail();const ids=new Set();for(const x of s[k]){if(!x||typeof x.id!=='string'||!/^[A-Za-z0-9_-]{1,80}$/.test(x.id)||ids.has(x.id))fail();ids.add(x.id)}}if(!s.accounts.length||s.accounts.length>50)fail();const named=x=>typeof x.name==='string'&&x.name.length>0&&x.name.length<=100;for(const a of s.accounts)if(!named(a)||!Number.isSafeInteger(a.opening)||Math.abs(a.opening)>1e12||!['bank','cash','ewallet'].includes(a.kind)||!/^#[0-9a-f]{6}$/i.test(a.color))fail();for(const c of s.categories)if(!named(c)||!['income','expense'].includes(c.type)||typeof c.icon!=='string'||c.icon.length>8||!/^#[0-9a-f]{6}$/i.test(c.color))fail();const acc=id=>s.accounts.some(a=>a.id===id);for(const t of s.transactions){if(!['income','expense','transfer'].includes(t.type)||!amount(t.amount)||!isDate(t.date)||!acc(t.account)||typeof t.note!=='string'||t.note.length>300)fail();if(t.billId!==undefined&&(!s.bills.some(b=>b.id===t.billId)||t.type!=='expense'))fail();if(t.type==='transfer'){if(!acc(t.to)||t.to===t.account)fail()}else if(!s.categories.some(c=>c.id===t.category&&c.type===t.type))fail()}const pairs=new Set();for(const b of s.budgets){const key=b.month+b.category;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(b.month)||!amount(b.limit)||!s.categories.some(c=>c.id===b.category&&c.type==='expense')||pairs.has(key))fail();pairs.add(key)}for(const g of s.goals)if(!named(g)||!amount(g.target)||!amount(g.saved,true)||g.saved>g.target||!isDate(g.deadline))fail();for(const b of s.bills)if(!named(b)||!amount(b.amount)||!Number.isInteger(b.day)||b.day<1||b.day>31||!acc(b.account)||!s.categories.some(c=>c.id===b.category&&c.type==='expense')||!Array.isArray(b.paid)||b.paid.some(m=>!/^\d{4}-(0[1-9]|1[0-2])$/.test(m)))fail();if(!Number.isSafeInteger(s.transactions.reduce((n,t)=>n+t.amount,0)))fail();for(const a of s.accounts)if(!Number.isSafeInteger(balance(s,a.id)))fail();return s}
export function demo(m=localDate().slice(0,7)){const s=empty();s.name='Agus';s.accounts=[{id:'bank',name:'Rekening utama',kind:'bank',opening:14800000,color:'#b7ce9b'},{id:'wallet',name:'Dompet digital',kind:'ewallet',opening:1000000,color:'#c5b9e0'},{id:'cash',name:'Tunai',kind:'cash',opening:300000,color:'#f0cca1'}];const add=(type,n,c,note,day,account='bank',to='')=>s.transactions.push({id:uid(),type,amount:n,category:c,note,date:`${m}-${String(day).padStart(2,'0')}`,account,to});add('income',8500000,'salary','Gaji bulanan',1);add('income',2000000,'freelance','Proyek desain website',7);add('expense',1500000,'bills','Sewa tempat tinggal',2);add('expense',325000,'bills','Internet rumah',3);add('expense',680000,'shopping','Belanja bulanan',5);add('expense',125000,'transport','Transportasi kerja',6,'wallet');add('expense',75000,'food','Makan siang',8,'wallet');add('expense',350000,'food','Belanja bahan masakan',9);add('expense',149000,'fun','Langganan hiburan',10);add('expense',85000,'food','Kopi & makan siang',12,'wallet');add('expense',225000,'health','Vitamin & obat',13);add('expense',485000,'shopping','Kebutuhan rumah',14);add('transfer',500000,'','Isi dompet digital',11,'bank','wallet');s.budgets=[{id:uid(),month:m,category:'food',limit:1500000},{id:uid(),month:m,category:'shopping',limit:1500000},{id:uid(),month:m,category:'transport',limit:600000},{id:uid(),month:m,category:'fun',limit:500000}];s.goals=[{id:uid(),name:'Dana darurat',target:30000000,saved:18000000,deadline:`${Number(m.slice(0,4))+1}-06-30`},{id:uid(),name:'Liburan ke Jepang',target:20000000,saved:6500000,deadline:`${Number(m.slice(0,4))+1}-12-01`}];s.bills=[{id:uid(),name:'Internet rumah',amount:325000,day:20,account:'bank',category:'bills',paid:[]},{id:uid(),name:'Langganan musik',amount:55000,day:25,account:'wallet',category:'fun',paid:[]}];return s}
export function csv(s,ts){const escape=v=>'"'+String(v??'').replace(/^[=+@\t\r-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Tanggal','Jenis','Kategori','Rekening','Tujuan transfer','Jumlah IDR','Catatan'],...ts.map(t=>[t.date,t.type,s.categories.find(c=>c.id===t.category)?.name||'Transfer',s.accounts.find(a=>a.id===t.account)?.name,s.accounts.find(a=>a.id===t.to)?.name||'',t.amount,t.note])];return '\uFEFF'+rows.map(r=>r.map(escape).join(',')).join('\r\n')}
